		public static EditorIcon GetIcon(string name) =>
			System.Enum.TryParse<FontAwesomeEditorIconType>(name, true, out var type) ? GetIcon(type) : null;

		public static EditorIcon GetLetterIcon(char letter, FontAwesomeEditorIconStyle style = FontAwesomeEditorIconStyle.Solid, FontAwesomeEditorIconShape shape = FontAwesomeEditorIconShape.Plain) => (style, shape) switch
		{
			(FontAwesomeEditorIconStyle.Regular, FontAwesomeEditorIconShape.Plain) => char.ToLowerInvariant(letter) switch
			{
				'a' => ARegular,
				'b' => BRegular,
				'c' => CRegular,
				'd' => DRegular,
				'e' => ERegular,
				'f' => FRegular,
